void display_init (void)
{	
  display_timeout = timeout_f_create(DISPLAY_TIMEOUT , display_pattern_update)  ;  

  display_irq_update = os_irq_create () ;   /// This must be done before Display task is started !!!
  tsk_display        = os_tsk_create (display_task, TASK_DISPLAY_PRI, TASK_DISPLAY_STK, 0, TASK_DISPLAY_NAME) ;
  
  os_tsk_start (tsk_display, 0) ;
}

